const _raw = $('POST /generate/orchestrated').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id   = $json.user_id;
const upload_id = (body.upload_id || '').toString().trim();
const brief     = (body.brief     || '').toString().trim();
const session_id = body.session_id ? body.session_id.toString() : null;
const room_hint  = body.room_type ? body.room_type.toString() : null;

const missing = [];
if (!upload_id) missing.push('upload_id');
if (!brief)     missing.push('brief');
if (missing.length) {
  return [{ json: { _error: { status: 400, body: { error: `missing_fields: ${missing.join(',')}`, code: 'invalid_request' } } } }];
}

const storage_path = `user-uploads/${user_id}/${upload_id}`;
const upload_url   = `${$env.SUPABASE_URL}/storage/v1/object/public/${storage_path}`;
return [{ json: { user_id, upload_id, brief, session_id, room_hint, upload_url, started_at_ms: Date.now() } }];

// Build the Agent 1 (orchestrator) OpenRouter request.
// Load the system prompt inline — source of truth: n8n/prompts/agent1_orchestrator.txt.
const bin  = $input.item.binary.image;
const b64  = bin.data;
const mime = bin.mimeType || 'image/png';
const dataUri = `data:${mime};base64,${b64}`;
const ctx  = $('Validate body').item.json;

const SYSTEM = `You are an interior-design reference retrieval and prompt-orchestration agent for Nano Banana 2.

Your mission: given a user's plain-language room prompt or design specification along with a photograph of the actual empty room, you must:
1. Interpret every usable specification in the prompt.
2. Critically reason about the room's 3D spatial structure as visible in the photograph.
3. Write the retrieval criteria that the next agent will use to pick exactly 3 reference images.
4. Use those criteria plus the user's specifications to write one curated Nano Banana 2 prompt.

Output format — STRICT. No preamble. No code fences. Exactly two delimited blocks:

===CRITERIA===
Room type & 3D structure notes:
<free-text grounded in the photograph>

Daylight & ambience target:
<free-text>

Style & material palette:
<free-text>

Functional requirements:
<free-text>

Complementarity guidance for the 3 references:
Reference 1 should best cover <spatial/layout logic>.
Reference 2 should best cover <style/materials/palette>.
Reference 3 should best cover <lighting/ambience/daylight>.
===END===

===PROMPT===
<one polished Nano Banana 2 creative brief: scene identity, 3D structure, functional layout, daylight & ambience, style & material language, camera & composition, image-quality constraints. Natural sentences, no keyword soup. Must instruct that the room geometry shown in the first input image is preserved. No people, no text, no logos.>
===END===`;

const openrouter_body = {
  model: $env.OPENROUTER_ORCHESTRATOR_MODEL || 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: [
      { type: 'text', text: `User brief:\n${ctx.brief}\n\nRoom type hint: ${ctx.room_hint || '(infer from photo)'}\n\nRoom photograph attached below. Ground all 3D reasoning in this image.` },
      { type: 'image_url', image_url: { url: dataUri } }
    ]}
  ],
  temperature: 0.4,
  max_tokens: 2048
};

return [{ json: { ...ctx, openrouter_body } }];

// Parse Agent 1 output. Extract ===CRITERIA=== and ===PROMPT=== blocks.
const ctx     = $('Build Agent 1 request').item.json;
const resp    = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
if (!content) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_empty_response', code: 'upstream_error' } } } }];
}

function extractBlock(text, startTag) {
  const startRe = new RegExp(`={3,}\\s*${startTag}\\s*={3,}`, 'i');
  const endRe   = /={3,}\s*END\s*={3,}/i;
  const s = text.search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  if (e < 0) return after.trim();
  return after.slice(0, e).trim();
}

const criteria = extractBlock(content, 'CRITERIA');
const prompt   = extractBlock(content, 'PROMPT');
if (!criteria || !prompt) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_bad_format', code: 'upstream_error', raw: content.slice(0, 500) } } } }];
}

// Try to extract a room_type from the criteria text for Agent 2 candidate filtering.
const roomWords = ['bedroom','living room','kitchen','dining room','bathroom','office','study','nursery','hallway','entryway'];
const lc = (criteria + ' ' + (ctx.brief || '')).toLowerCase();
let inferred_room = ctx.room_hint;
if (!inferred_room) {
  for (const w of roomWords) { if (lc.includes(w)) { inferred_room = w.replace(' ', '_'); break; } }
}

return [{ json: { ...ctx, criteria, agent_prompt: prompt, inferred_room } }];

// If room-type-filtered pool is empty, fall back to unfiltered top 60.
const rows = Array.isArray($json) ? $json : ($json.body || []);
const ctx  = $('Parse Agent 1').item.json;
if (rows.length >= 3) {
  return [{ json: { ...ctx, pool: rows, pool_fallback: false } }];
}
return [{ json: { ...ctx, pool: rows, pool_fallback: true } }];

const rows = Array.isArray($json) ? $json : ($json.body || []);
const ctx  = $('Check pool').item.json;
return [{ json: { ...ctx, pool: rows } }];

// Build Agent 2 request: system prompt + criteria + candidate pool as cards.
const ctx  = $json;
const pool = ctx.pool || [];
if (pool.length < 3) {
  return [{ json: { _error: { status: 500, body: { error: 'pool_too_small', code: 'internal_error', count: pool.length } } } }];
}

const SYSTEM = `You are a reference-image selector working under a design director's written criteria.

You will receive: (1) a retrieval-criteria block, (2) a pool of candidates printed as one-line cards:
   [id=<uuid>] caption — room: <room_type> — style: [<tags>] — colors: [<hex>] — objects: [<items>] — q=<quality>

Pick exactly 3 ids whose combined coverage best satisfies the criteria. Reference 1 → spatial/layout; Reference 2 → style/materials/palette; Reference 3 → lighting/ambience. Complementary, not redundant. Never invent ids. Never pick duplicates.

Output — STRICT. Exactly three lines. No preamble, no JSON, no code fences:
Reference 1: <uuid> — <one short sentence justifying the pick>
Reference 2: <uuid> — <one short sentence justifying the pick>
Reference 3: <uuid> — <one short sentence justifying the pick>`;

const cards = pool.map(r => {
  const style = Array.isArray(r.style_tags) ? r.style_tags.join(',') : '';
  const colors = Array.isArray(r.dominant_colors) ? r.dominant_colors.join(',') : '';
  const objects = Array.isArray(r.detected_objects) ? r.detected_objects.join(',') : '';
  const cap = (r.caption || '').replace(/\s+/g, ' ').trim().slice(0, 140);
  return `[id=${r.id}] ${cap} — room: ${r.room_type || '?'} — style: [${style}] — colors: [${colors}] — objects: [${objects}] — q=${r.quality_score ?? '?'}`;
}).join('\n');

const user = `===CRITERIA===\n${ctx.criteria}\n===END===\n\n===CANDIDATES===\n${cards}\n===END===`;

const openrouter_body = {
  model: $env.OPENROUTER_RETRIEVER_MODEL || $env.OPENROUTER_ORCHESTRATOR_MODEL || 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user',   content: user }
  ],
  temperature: 0.2,
  max_tokens: 512
};

return [{ json: { ...ctx, openrouter_body } }];

// Parse three UUIDs from Agent 2 output, validate against pool, dedupe.
const ctx  = $('Build Agent 2 request').item.json;
const resp = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
const uuidRe = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
const matches = (content.match(uuidRe) || []).map(s => s.toLowerCase());

const poolIds = new Set((ctx.pool || []).map(r => r.id.toLowerCase()));
const seen = new Set();
const picks = [];
for (const m of matches) {
  if (!poolIds.has(m)) continue;
  if (seen.has(m)) continue;
  seen.add(m);
  picks.push(m);
  if (picks.length === 3) break;
}

// Fallback: if fewer than 3 valid picks, top up from pool by quality_score.
if (picks.length < 3) {
  const sorted = [...(ctx.pool || [])].sort((a, b) => (b.quality_score || 0) - (a.quality_score || 0));
  for (const r of sorted) {
    const id = r.id.toLowerCase();
    if (seen.has(id)) continue;
    seen.add(id);
    picks.push(id);
    if (picks.length === 3) break;
  }
}

if (picks.length < 3) {
  return [{ json: { _error: { status: 500, body: { error: 'retriever_picks_too_few', code: 'internal_error' } } } }];
}

return [{ json: { ...ctx, picked_reference_ids: picks } }];

const ctx  = $('Parse Agent 2').item.json;
const refs = Array.isArray($json) ? $json : ($json.body || []);
const byId = {};
refs.forEach(r => { byId[r.id.toLowerCase()] = r.source_url; });

// Ordered fetch list: upload first, then 3 references in the order Agent 2 returned.
const urls = [ctx.upload_url];
for (const id of ctx.picked_reference_ids) {
  if (byId[id]) urls.push(byId[id]);
}
if (urls.length !== 4) {
  return [{ json: { _error: { status: 500, body: { error: 'picked_reference_url_missing', code: 'internal_error' } } } }];
}
return urls.map((url, i) => ({ json: { ...ctx, idx: i, fetch_url: url } }));

const items = $input.all();
items.sort((a, b) => a.json.idx - b.json.idx);
const parts = items.map(it => ({
  inline_data: {
    mime_type: it.binary.image.mimeType || 'image/png',
    data:      it.binary.image.data
  }
}));
return [{ json: { ...items[0].json, image_parts: parts } }];

const rows  = Array.isArray($json) ? $json : ($json.body || []);
const model = (rows[0] && rows[0].value) || 'gemini-3.1-flash-image-preview';
const ctx   = $('Collect image parts').item.json;

const gemini_body = {
  contents: [{
    role: 'user',
    parts: [ { text: ctx.agent_prompt }, ...ctx.image_parts ]
  }],
  generationConfig: { responseModalities: ['IMAGE'] }
};

return [{ json: { ...ctx, model, gemini_body } }];

const ctx  = $('Build Gemini request').item.json;
const resp = $json;
const parts = (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts) || [];
const imgPart = parts.find(p => p.inlineData || p.inline_data);
if (!imgPart) {
  return [{ json: { _error: { status: 502, body: { error: 'no_image_in_response', code: 'upstream_error' } } } }];
}
const inline = imgPart.inlineData || imgPart.inline_data;
const b64    = inline.data;
const mime   = inline.mimeType || inline.mime_type || 'image/png';
const latency_ms = Date.now() - ctx.started_at_ms;

return [{
  json: {
    user_id:             ctx.user_id,
    session_id:          ctx.session_id,
    parent_generation_id: null,
    kind:                'orchestrated',
    input_image_path:    `user-uploads/${ctx.user_id}/${ctx.upload_id}`,
    room_type:           ctx.inferred_room || null,
    style_tag:           null,
    reference_image_ids: ctx.picked_reference_ids,
    prompt:              ctx.agent_prompt,
    criteria:            ctx.criteria,
    model_config:        'A',
    model_id:            ctx.model,
    latency_ms,
    cost_usd:            0
  },
  binary: { output_png: { data: b64, mimeType: mime, fileExtension: 'png', fileName: 'output.png' } }
}];

parameters.responseBody:
={{ JSON.stringify({
  generation_id:       $json.generation_id,
  output_url:          $json.output_url,
  latency_ms:          $json.latency_ms,
  cost_usd:            $json.cost_usd,
  model_id:            $json.model_id,
  backend_id:          'gemini',
  reference_image_ids: $('Parse Agent 2').item.json.picked_reference_ids,
  criteria:            $('Parse Agent 1').item.json.criteria
}) }}
